-- AI-proposed code changes and sandboxed verification runs.
--
-- A code change is a proposal: edits generated by an AI model against one
-- analyzed version, applied by the server to the stored sources and kept
-- as a unified diff. USIE never writes to the repository; a proposal is
-- unverified until a verification run passes.

CREATE TABLE code_changes (
    id               uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    organization_id  uuid NOT NULL,
    repository_id    uuid NOT NULL,
    version_id       uuid NOT NULL,
    -- What was asked for, and the optional node it is about.
    request          text NOT NULL CHECK (length(request) BETWEEN 1 AND 4000),
    focus_key        text NOT NULL DEFAULT '',
    -- pending → proposed | declined | failed; proposed → discarded.
    status           text NOT NULL DEFAULT 'pending'
                     CHECK (status IN ('pending', 'proposed', 'declined', 'failed', 'discarded')),
    summary          text NOT NULL DEFAULT '',
    rationale        text NOT NULL DEFAULT '',
    risks            jsonb NOT NULL DEFAULT '[]',
    test_plan        jsonb NOT NULL DEFAULT '[]',
    limitations      jsonb NOT NULL DEFAULT '[]',
    -- The validated edits as returned by the model, and the diff the
    -- server produced by applying them.
    edits            jsonb NOT NULL DEFAULT '[]',
    -- The resulting content of every file the change touches:
    -- [{path, status: modified | created | deleted, content}].
    files            jsonb NOT NULL DEFAULT '[]',
    diff             text NOT NULL DEFAULT '',
    files_changed    integer NOT NULL DEFAULT 0,
    lines_added      integer NOT NULL DEFAULT 0,
    lines_removed    integer NOT NULL DEFAULT 0,
    -- Change impact of the diff on the version (ADR 0010).
    impact           jsonb NOT NULL DEFAULT '{}',
    -- The evidence sent to the model (ids, keys, paths, lines).
    context          jsonb NOT NULL DEFAULT '[]',
    provider         text NOT NULL DEFAULT '',
    model            text NOT NULL DEFAULT '',
    input_tokens     integer NOT NULL DEFAULT 0,
    output_tokens    integer NOT NULL DEFAULT 0,
    cache_read_tokens integer NOT NULL DEFAULT 0,
    latency_ms       integer NOT NULL DEFAULT 0,
    error            text NOT NULL DEFAULT '',
    created_by       uuid REFERENCES users(id) ON DELETE SET NULL,
    created_at       timestamptz NOT NULL DEFAULT now(),
    completed_at     timestamptz,
    UNIQUE (organization_id, id),
    FOREIGN KEY (organization_id, version_id) REFERENCES repository_versions (organization_id, id) ON DELETE CASCADE
);
CREATE INDEX code_changes_repo_idx ON code_changes (organization_id, repository_id, created_at DESC);
CREATE INDEX code_changes_usage_idx ON code_changes (organization_id, created_at);
CREATE INDEX code_changes_user_idx ON code_changes (created_by, created_at);
CREATE INDEX code_changes_pending_idx ON code_changes (created_at) WHERE status = 'pending';

-- One run of a verification profile (build and tests) in the sandbox,
-- optionally against the unchanged version first (baseline).
CREATE TABLE verification_runs (
    id               uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    organization_id  uuid NOT NULL,
    repository_id    uuid NOT NULL,
    version_id       uuid NOT NULL,
    change_id        uuid NOT NULL,
    profile          text NOT NULL,
    baseline         boolean NOT NULL DEFAULT true,
    -- queued → running → passed | failed | error | cancelled
    status           text NOT NULL DEFAULT 'queued'
                     CHECK (status IN ('queued', 'running', 'passed', 'failed', 'error', 'cancelled')),
    -- {baseline: {steps: [...]}, change: {steps: [...]}, missing_files, sandbox}
    result           jsonb NOT NULL DEFAULT '{}',
    error            text NOT NULL DEFAULT '',
    created_by       uuid REFERENCES users(id) ON DELETE SET NULL,
    created_at       timestamptz NOT NULL DEFAULT now(),
    started_at       timestamptz,
    finished_at      timestamptz,
    UNIQUE (organization_id, id),
    FOREIGN KEY (organization_id, change_id) REFERENCES code_changes (organization_id, id) ON DELETE CASCADE,
    FOREIGN KEY (organization_id, version_id) REFERENCES repository_versions (organization_id, id) ON DELETE CASCADE
);
CREATE INDEX verification_runs_change_idx ON verification_runs (organization_id, change_id, created_at DESC);

-- Verification runs are executed by workers through the job queue.
ALTER TABLE analysis_jobs DROP CONSTRAINT analysis_jobs_kind_check;
ALTER TABLE analysis_jobs ADD CONSTRAINT analysis_jobs_kind_check CHECK (kind IN ('analyze_version', 'verify_change'));
ALTER TABLE analysis_jobs ADD COLUMN subject_id uuid;
